@startuml

enum RequestType {
  SOBER_APP
  HAND_WAVING
}

class Car {
  + LicensePlate : string
}

class Owner {
  + Name : string
}

class Accident {
  + Date : date
  + Location : string
  + DamageAmount : float
}

class RideHail {
  + PickUpTime : time
  + DropOffTime : time
  + PickUpLocation : string
  + DropOffLocation : string
  + RideDuration : string
  + Distance : float
  + PassengerCount : int
  + Fee : float
  + RequestType : RequestType
}

class RideShare {
  + PickUpTime : time
  + DropOffTime : time
  + PickUpLocation : string
  + DropOffLocation : string
  + RideDuration : string
  + Distance : float
  + NegotiatedFee : float
}

class Customer {
  + Name : string
}

class RideHailCustomer {
  + Name : string
}

class RideShareCustomer {
  + Name : string
}

class CarOwner extends Owner {}
class Customer extends Customer {}
class RideHailCustomer extends Customer {}
class RideShareCustomer extends Customer {}

Car "1" -- "*" Accident
Car "1" -- "*" RideHail
Car "1" -- "*" RideShare
Car "0..1" -- "1" Owner : owned by
RideHail "*" -- "1" RideHailCustomer : lead customer
RideShare "*" -- "1..10" RideShareCustomer : passengers

@enduml

